mapper.select:
SELECT 
  FROM project_locations
 WHERE project_id = #{projectId}
   AND status = 'ACTIVE'
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}

SELECT 
  FROM project_locations
 WHERE project_id = #{projectId}
   AND status = 'ACTIVE'
   AND (updated_at < #{updatedAt}
        OR (updated_at = #{updatedAt} AND id < #{id}))
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}

SELECT 
  FROM project_assets
 WHERE project_id = #{projectId}
   AND status = 'ACTIVE'
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}

SELECT 
  FROM project_assets
 WHERE project_id = #{projectId}
   AND status = 'ACTIVE'
   AND (updated_at < #{updatedAt}
        OR (updated_at = #{updatedAt} AND id < #{id}))
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}
